        code += '    roi=roi,\n';
        code += '    out_gif="landsat_timelapse.gif",\n';
        code += '    start_year=config["start_year"],\n';
        code += '    end_year=config["end_year"],\n';
        code += '    start_date=config["start_date"],\n';
        code += '    end_date=config["end_date"],\n';
        code += '    bands=config["bands"],\n';
        code += '    dimensions=config["dimensions"],\n';
        code += '    frames_per_second=config["frames_per_second"],\n';
        code += '    apply_fmask=True,\n';
        code += ')\n';
        code += 'print("✅ Timelapse creado: landsat_timelapse.gif")\n';

